// EVM 256-bit modular arithmetic spec-vector integration test.
//
// Vectors generated by Python `(a * b) % m` and `(a + b) % m` over canonical
// 256-bit unsigned integers. The luxcpp body documents that when m == 0 the
// C-ABI returns CRYPTO_ERR_INPUT (the caller is expected to map zero-modulus
// to a zero result before calling, matching EVM precompile dispatch
// behavior).

use lux_crypto_evm256::{addmod, mulmod, WORD_LEN};

fn from_hex(s: &str) -> [u8; WORD_LEN] {
    let s = s.as_bytes();
    assert_eq!(s.len(), 2 * WORD_LEN);
    let mut out = [0u8; WORD_LEN];
    let nibble = |c: u8| -> u8 {
        match c {
            b'0'..=b'9' => c - b'0',
            b'a'..=b'f' => c - b'a' + 10,
            b'A'..=b'F' => c - b'A' + 10,
            _ => panic!("non-hex"),
        }
    };
    for i in 0..WORD_LEN {
        out[i] = (nibble(s[2 * i]) << 4) | nibble(s[2 * i + 1]);
    }
    out
}

struct V {
    name: &'static str,
    a: &'static str,
    b: &'static str,
    m: &'static str,
    mul: &'static str,
    add: &'static str,
}

