#[test]
fn published_vectors_byte_equal() {
    for v in VECTORS {
        let a = from_hex(v.a);
        let b = from_hex(v.b);
        let m = from_hex(v.m);
        let want_mul = from_hex(v.mul);
        let want_add = from_hex(v.add);
        let got_mul = mulmod(&a, &b, &m).unwrap_or_else(|e| panic!("{}: mulmod {:?}", v.name, e));
        let got_add = addmod(&a, &b, &m).unwrap_or_else(|e| panic!("{}: addmod {:?}", v.name, e));
        assert_eq!(got_mul, want_mul, "{}: mulmod mismatch", v.name);
        assert_eq!(got_add, want_add, "{}: addmod mismatch", v.name);
    }
}

#[test]
fn word_len_constant() {
    assert_eq!(WORD_LEN, 32);
}

#[test]
fn zero_modulus_returns_bad_input() {
    let zero = [0u8; WORD_LEN];
    let one = {
        let mut o = [0u8; WORD_LEN];
        o[31] = 1;
        o
    };
    assert!(mulmod(&one, &one, &zero).is_err());
    assert!(addmod(&one, &one, &zero).is_err());
}

#[test]
fn deterministic_repeated_calls() {
    let a = from_hex("0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20");
    let b = from_hex("2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40");
    let m = from_hex("73eda753299d7d483339d80809a1d80553bda402fffe5bfeffffffff00000001");
    let r1 = mulmod(&a, &b, &m).unwrap();
    let r2 = mulmod(&a, &b, &m).unwrap();
    assert_eq!(r1, r2);
}
